/* Наклон карточки за курсором.
   Зона .tilt слушает указатель и сама не наклоняется: её рамка стабильна, и у краёв карточка не дрожит.
   Наклоняется только .tilt__card (это делает JS). Подъём и тень — чистый CSS: работают без JS и с клавиатуры. */
.tilt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px;margin:0;padding:0;list-style:none;}
.tilt{position:relative;isolation:isolate;border-radius:var(--tilt-radius,20px);transition:transform 240ms cubic-bezier(.2,0,0,1);}
/* Мягкая тень отдельным слоем: размытие считается один раз, на наведении меняется только opacity */
.tilt::before{content:"";position:absolute;inset:12% 8% -4%;z-index:-1;border-radius:inherit;background:var(--tilt-shadow,rgba(15,23,42,.28));filter:blur(24px);opacity:0;pointer-events:none;transition:opacity 240ms cubic-bezier(.2,0,0,1);}
.tilt__card{position:relative;isolation:isolate;box-sizing:border-box;height:100%;overflow:hidden;border-radius:inherit;padding:28px;background:var(--surface,#ffffff);color:var(--text,#0f172a);border:1px solid var(--border,#d9dee7);transform-origin:50% 50%;}
/* Блик: пятно света вдвое больше карточки, JS двигает его за курсором. Лежит под текстом, но подсвечивает фон под ним
   и снижает контраст текста на 10–17 %. Поэтому яркость строго такая: светлая карточка — акцент с прозрачностью .10
   (по умолчанию), тёмная — --tilt-glare: rgba(255,255,255,.06), не ярче. Если text_muted или link на surface дают
   меньше 5.5:1, блик выключите: --tilt-glare: transparent */
.tilt__glare{position:absolute;inset:-50%;background:radial-gradient(circle at 50% 50%,var(--tilt-glare,rgba(37,99,235,.10)),transparent 40%);opacity:0;pointer-events:none;transition:opacity 240ms cubic-bezier(.2,0,0,1);}
.tilt__body{position:relative;}
.tilt__title{margin:0 0 8px;font-size:22px;line-height:1.25;}
.tilt__text{margin:0 0 20px;line-height:1.5;color:var(--text-muted,#475569);}
.tilt__link{font-weight:600;color:var(--link,#1d4ed8);}
.tilt__link:focus-visible{outline:2px solid currentColor;outline-offset:3px;border-radius:4px;}
/* Подъём: мышь над карточкой и фокус с клавиатуры внутри неё дают одно и то же состояние */
@media (hover: hover) and (pointer: fine){
  .tilt:hover{z-index:2;transform:scale(1.03);}
  .tilt:hover::before{opacity:1;}
}
.tilt:has(:focus-visible){z-index:2;transform:scale(1.03);}
.tilt:has(:focus-visible)::before{opacity:1;}
/* Состояния ставит JS: on — курсор над карточкой, settle — карточка возвращается на место.
   will-change нужен и блику: без своего слоя браузер перерисовывает всю карточку на каждом кадре движения */
.tilt[data-tilt-state] .tilt__card,.tilt[data-tilt-state] .tilt__glare{will-change:transform;}
.tilt[data-tilt-state="on"] .tilt__glare{opacity:1;}
/* Уменьшение движения (три уровня). Убираем: 3D-наклон, подъём и блик. Смягчаем: тень проявляется за 150 мс.
   Оставляем: кольцо фокуса. !important перебивает и встроенный стиль, если JS успел его поставить */
@media (prefers-reduced-motion: reduce){
  .tilt,.tilt__card{transform:none!important;transition:none;}
  .tilt__glare{display:none;}
  .tilt::before{transition:opacity 150ms linear;}
}
@media print{
  .tilt,.tilt__card{transform:none!important;}
  .tilt__glare,.tilt::before{display:none;}
}

