// Подключать в конце body или с defer: скрипт ищет карточки один раз при запуске.
(() => {
  const fine = matchMedia('(hover: hover) and (pointer: fine)');
  const calm = matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = v => Math.min(Math.max(v, 0), 1);
  document.querySelectorAll('[data-tilt]').forEach(zone => {
    const card = zone.querySelector('.tilt__card'), glare = zone.querySelector('.tilt__glare');
    if (!card) return;
    const m = parseFloat(zone.dataset.tiltMax), max = Math.min(Math.max(Number.isFinite(m) ? m : 6, 0), 8); // градусы: по умолчанию 6, 0 — без наклона, потолок 8
    let on = false, raf = 0, last = 0, px = 0, py = 0, tx = 0, ty = 0, x = 0, y = 0;
    const draw = now => {
      if (on) { // рамку зоны читаем раз за кадр и до записи стилей
        const r = zone.getBoundingClientRect();
        tx = clamp((px - r.left) / r.width) - 0.5; ty = clamp((py - r.top) / r.height) - 0.5;
      }
      const k = 1 - Math.pow(0.84, (last ? Math.min(now - last, 64) : 16.7) / 16.7); // одинаково на 60 и 120 Гц
      last = now; x += (tx - x) * k; y += (ty - y) * k;
      card.style.transform = `perspective(900px) rotateX(${(-y * 2 * max).toFixed(2)}deg) rotateY(${(x * 2 * max).toFixed(2)}deg)`;
      if (glare) glare.style.transform = `translate(${(x * 50).toFixed(2)}%, ${(y * 50).toFixed(2)}%)`;
      if (Math.abs(tx - x) + Math.abs(ty - y) > 0.002) { raf = requestAnimationFrame(draw); return; }
      raf = 0; last = 0; // карточка встала — цикл остановлен, работы ноль
      if (!on) { card.style.transform = ''; if (glare) glare.style.transform = ''; zone.removeAttribute('data-tilt-state'); }
    };
    const kick = () => { if (!raf) raf = requestAnimationFrame(draw); };
    const move = e => {
      if (e.pointerType === 'touch' || !fine.matches || calm.matches) return; // тач и «уменьшить движение» — без наклона
      px = e.clientX; py = e.clientY;
      if (!on) { on = true; zone.setAttribute('data-tilt-state', 'on'); }
      kick();
    };
    zone.addEventListener('pointerenter', move);
    zone.addEventListener('pointermove', move);
    zone.addEventListener('pointerleave', () => {
      if (!on) return;
      on = false; tx = ty = 0; zone.setAttribute('data-tilt-state', 'settle'); kick();
    });
  });
})();

