// Установка из npm, без CDN: npm i gsap (своя бесплатная Standard License, это не MIT).
// Разметка и CSS те же, ванильный скрипт не подключайте. Подъём и тень остаются в CSS, GSAP ведёт только наклон и блик.
import gsap from 'gsap';
const mm = gsap.matchMedia();
mm.add('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)', () => { // иначе ничего не создаём
  const offs = [], clamp = gsap.utils.clamp(0, 1);
  gsap.utils.toArray('[data-tilt]').forEach(zone => {
    const card = zone.querySelector('.tilt__card'), glare = zone.querySelector('.tilt__glare');
    if (!card) return;
    const m = parseFloat(zone.dataset.tiltMax), max = Math.min(Math.max(Number.isFinite(m) ? m : 6, 0), 8);
    const to = (el, prop) => el ? gsap.quickTo(el, prop, { duration: 0.45, ease: 'power3' }) : () => {}; // один твин на свойство, не твин на событие
    gsap.set(card, { transformPerspective: 900 });
    const rx = to(card, 'rotationX'), ry = to(card, 'rotationY'), gx = to(glare, 'xPercent'), gy = to(glare, 'yPercent');
    const move = e => {
      if (e.pointerType === 'touch') return;
      const r = zone.getBoundingClientRect(); // меряем на каждом движении: прокрутка сдвигает рамку
      const x = clamp((e.clientX - r.left) / r.width) - 0.5, y = clamp((e.clientY - r.top) / r.height) - 0.5;
      if (zone.dataset.tiltState !== 'on') zone.dataset.tiltState = 'on';
      rx(-y * 2 * max); ry(x * 2 * max); gx(x * 50); gy(y * 50);
    };
    const leave = () => { // settle держит will-change, пока карточка возвращается (0,45 с), потом снимаем
      zone.dataset.tiltState = 'settle'; rx(0); ry(0); gx(0); gy(0);
      gsap.delayedCall(0.5, () => { if (zone.dataset.tiltState === 'settle') delete zone.dataset.tiltState; });
    };
    zone.addEventListener('pointermove', move);
    zone.addEventListener('pointerleave', leave);
    offs.push(() => { zone.removeEventListener('pointermove', move); zone.removeEventListener('pointerleave', leave); delete zone.dataset.tiltState; });
  });
  return () => offs.forEach(off => off()); // gsap.matchMedia сам откатит gsap.set и твины
});
